"use client"

import * as React from "react"
import { Bell } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { EmptyState } from "@atlas/ui-web/compositions/EmptyState/EmptyState"
import {
  ListItem,
  ListItemActions,
  ListItemContent,
  ListItemDescription,
  ListItemMedia,
  ListItemTitle,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import { TabsList, TabsRoot, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { Avatar } from "@atlas/ui-web/primitives/Avatar/Avatar"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { FlowShell } from "../_shared/FlowShell"
import { SAMPLE_NOTIFICATIONS, type Notification } from "./data"

type Status = "loading" | "ready" | "error"

const titleStyle: React.CSSProperties = {
  margin: 0,
  fontSize: "var(--atlas-text-h1)",
  fontWeight: "var(--atlas-font-weight-semibold)",
  lineHeight: "var(--atlas-line-height-tight)",
  color: "var(--atlas-foreground)",
}
const visuallyHidden: React.CSSProperties = {
  position: "absolute",
  inlineSize: 1,
  blockSize: 1,
  overflow: "hidden",
  clipPath: "inset(50%)",
}
const linkStyle: React.CSSProperties = { color: "inherit", textDecoration: "none" }

/**
 * Preview the other states with a query param:
 *   ?state=error   first load fails, Retry succeeds
 *   ?state=empty   the account has no notifications
 */
function readMode(): string | null {
  return new URLSearchParams(window.location.search).get("state")
}

export default function NotificationsPage() {
  const [status, setStatus] = React.useState<Status>("loading")
  const [items, setItems] = React.useState<Notification[]>([])
  const [view, setView] = React.useState("all")
  const [announce, setAnnounce] = React.useState("")
  const [approving, setApproving] = React.useState<string | null>(null)
  const failNext = React.useRef<boolean | null>(null)
  const timers = React.useRef<number[]>([])

  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms))
  }

  const load = React.useCallback(() => {
    const mode = readMode()
    if (failNext.current === null) failNext.current = mode === "error"
    setStatus("loading")
    timers.current.push(
      window.setTimeout(() => {
        if (failNext.current) {
          failNext.current = false
          setStatus("error")
          return
        }
        setItems(mode === "empty" ? [] : SAMPLE_NOTIFICATIONS)
        setStatus("ready")
      }, 900),
    )
  }, [])

  React.useEffect(() => {
    load()
    const pending = timers.current
    return () => pending.forEach((t) => window.clearTimeout(t))
  }, [load])

  const unread = items.filter((n) => !n.read)
  const shown = view === "unread" ? unread : items

  const setRead = (id: string, read: boolean) =>
    setItems((prev) => prev.map((n) => (n.id === id ? { ...n, read } : n)))

  const toggle = (n: Notification) => {
    setRead(n.id, !n.read)
    setAnnounce(n.read ? "Marked as unread" : "Marked as read")
  }

  const markAll = () => {
    setItems((prev) => prev.map((n) => ({ ...n, read: true })))
    setAnnounce("All notifications marked as read")
  }

  const approve = (n: Notification) => {
    setApproving(n.id)
    later(() => {
      setItems((prev) => prev.map((x) => (x.id === n.id ? { ...x, approved: true, read: true } : x)))
      setApproving(null)
      setAnnounce("Approved")
    }, 800)
  }

  const loaded = status === "ready"

  return (
    <FlowShell
      title="Notifications"
      step={0}
      totalSteps={1}
      showProgress={false}
      phoneBackground="var(--atlas-background)"
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-4)",
          paddingInline: "var(--atlas-spacing-4)",
          paddingBlockEnd: "var(--atlas-spacing-6)",
        }}
      >
        <header
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: "var(--atlas-spacing-3)",
          }}
        >
          <h1 style={titleStyle}>Notifications</h1>
          <Button variant="ghost" size="sm" disabled={!loaded || unread.length === 0} onClick={markAll}>
            Mark all as read
          </Button>
        </header>

        <TabsRoot variant="line" size="md" value={view} onValueChange={setView}>
          <TabsList aria-label="Notification views">
            <TabsTrigger value="all">All</TabsTrigger>
            <TabsTrigger value="unread">{loaded ? `Unread ${unread.length}` : "Unread"}</TabsTrigger>
          </TabsList>
        </TabsRoot>

        <div role="status" style={visuallyHidden}>
          {announce}
        </div>

        {status === "loading" && (
          <div
            role="status"
            aria-busy="true"
            aria-label="Loading notifications"
            style={{ display: "grid", gap: "var(--atlas-spacing-2)" }}
          >
            {[0, 1, 2, 3].map((i) => (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "var(--atlas-spacing-3)",
                  padding: "var(--atlas-spacing-3)",
                }}
              >
                <div style={{ inlineSize: "var(--atlas-spacing-8)", flexShrink: 0 }}>
                  <Skeleton shape="circle" style={{ blockSize: "var(--atlas-spacing-8)" }} />
                </div>
                <div style={{ flex: 1, display: "grid", gap: "var(--atlas-spacing-2)" }}>
                  <Skeleton />
                  <Skeleton style={{ inlineSize: "60%" }} />
                </div>
              </div>
            ))}
          </div>
        )}

        {status === "error" && (
          <Alert
            variant="danger"
            title="Couldn’t load notifications"
            description="Check your connection and try again."
            actions={
              <Button variant="outline" size="sm" onClick={load}>
                Retry
              </Button>
            }
          />
        )}

        {loaded && shown.length === 0 && (
          <EmptyState
            size="md"
            icon={<Bell />}
            title={view === "unread" ? "No unread notifications" : "You’re all caught up"}
            description={
              view === "unread"
                ? "Everything has been read."
                : "New activity will show up here."
            }
            action={
              view === "unread" && items.length > 0 ? (
                <Button variant="outline" onClick={() => setView("all")}>
                  View all
                </Button>
              ) : undefined
            }
          />
        )}

        {loaded && shown.length > 0 && (
          <ul
            aria-label={view === "unread" ? "Unread notifications" : "All notifications"}
            style={{
              display: "grid",
              gap: "var(--atlas-spacing-2)",
              listStyle: "none",
              margin: 0,
              padding: 0,
            }}
          >
            {shown.map((n) => (
              <ListItem key={n.id} as="li" variant={n.read ? "default" : "muted"} size="md">
                <ListItemMedia>
                  <Avatar size="sm" initials={n.initials} alt="" />
                </ListItemMedia>
                <ListItemContent>
                  <ListItemTitle>
                    <a
                      href="#"
                      style={linkStyle}
                      onClick={(e) => {
                        e.preventDefault()
                        if (!n.read) setRead(n.id, true)
                      }}
                    >
                      {n.title}
                    </a>
                  </ListItemTitle>
                  <ListItemDescription>
                    {!n.read && "Unread · "}
                    {n.approved && "Approved · "}
                    {n.place} · <time dateTime={n.dateTime}>{n.when}</time>
                  </ListItemDescription>
                </ListItemContent>
                <ListItemActions>
                  <div
                    style={{
                      display: "flex",
                      flexWrap: "wrap",
                      justifyContent: "flex-end",
                      gap: "var(--atlas-spacing-1)",
                    }}
                  >
                    {n.kind === "approval" && !n.approved && (
                      <Button
                        variant="outline"
                        size="sm"
                        loading={approving === n.id}
                        aria-label={`Approve “${n.title}”`}
                        onClick={() => approve(n)}
                      >
                        Approve
                      </Button>
                    )}
                    <Button
                      variant="ghost"
                      size="sm"
                      aria-label={`Mark “${n.title}” as ${n.read ? "unread" : "read"}`}
                      onClick={() => toggle(n)}
                    >
                      {n.read ? "Mark as unread" : "Mark as read"}
                    </Button>
                  </div>
                </ListItemActions>
              </ListItem>
            ))}
          </ul>
        )}
      </div>
    </FlowShell>
  )
}

